(function VASCULAR_TUDO() {
  const R = {};
  R.url = location.href;
  R.title = document.title;
  R.meta = [...document.querySelectorAll('meta')].map(m => ({n: m.name||m.getAttribute('property'), c: m.content}));
  R.scripts = [...document.scripts].map(s => s.src || 'inline');
  R.links = [...document.querySelectorAll('link')].map(l => ({rel: l.rel, href: l.href}));
  R.inputs = [...document.querySelectorAll('input,textarea,select')].map(i => ({tag: i.tagName, name: i.name, id: i.id, type: i.type, value: i.value}));
  R.forms = [...document.forms].map(f => ({action: f.action, method: f.method, fields: [...f.elements].map(e => e.name)}));
  R.dataAttrs = [...document.querySelectorAll('*')].filter(e => [...e.attributes].some(a => a.name.startsWith('data-'))).map(e => ({tag: e.tagName, attrs: [...e.attributes].filter(a => a.name.startsWith('data-')).map(a => [a.name, a.value])}));
  R.comments = (document.documentElement.outerHTML.match(/<!--[\s\S]*?-->/g) || []);
  R.hiddenElements = [...document.querySelectorAll('*')].filter(e => {
    const s = getComputedStyle(e);
    return s.display === 'none' || s.visibility === 'hidden' || s.opacity === '0';
  }).map(e => ({tag: e.tagName, id: e.id, class: e.className}));
  R.storage = {
    local: {...localStorage},
    session: {...sessionStorage},
    cookies: document.cookie
  };
  R.resources = performance.getEntriesByType('resource').map(r => r.name);
  R.apiEndpoints = [...new Set(R.resources.filter(u => u.includes('/api/') || u.includes('/v1/') || u.includes('/v2/') || u.includes('/graphql')))];
  R.frameworkState = window.__INITIAL_STATE__ || window.__NUXT__ || window.__NEXT_DATA__ || window._sharedData || null;
  return R;
})();

auditoria_total.script_unificado_devtools:
(() => {
  console.group('🛡️ [SENTINELA] INSPEÇÃO IRRESTRITA DE INTERFACE & DEPURAÇÃO DOM');
  const rel = {
    senhasDesmascaradas: 0,
    travasCssRemovidas: 0,
    camposDesbloqueados: 0,
    overlaysRemovidos: 0,
    valoresCacheColetados: [],
    metadadosAriaColetados: []
  };

  // 1. Desmascaramento de inputs confidenciais (password -> text)
  document.querySelectorAll('input[type="password"]').forEach((i) => {
    i.type = 'text';
    i.setAttribute('data-sentinela-unmasked', 'true');
    i.style.border = '2px dashed #f59e0b';
    rel.senhasDesmascaradas++;
  });

  // 2. Sobrescrita de regras de segurança visual CSS (blur, text-security)
  document.querySelectorAll('*').forEach((el) => {
    const s = window.getComputedStyle(el);
    let mod = false;
    if (s.filter && s.filter !== 'none') { el.style.filter = 'none'; mod = true; }
    if (s.webkitTextSecurity && s.webkitTextSecurity !== 'none') { el.style.webkitTextSecurity = 'none'; mod = true; }
    if (s.textSecurity && s.textSecurity !== 'none') { el.style.textSecurity = 'none'; mod = true; }
    if (s.userSelect === 'none') { el.style.userSelect = 'text'; mod = true; }
    if (mod) rel.travasCssRemovidas++;
  });

  // 3. Liberação de estados de elementos (disabled / readonly)
  document.querySelectorAll('input, select, textarea, button').forEach((el) => {
    let d = false;
    if (el.hasAttribute('disabled')) { el.removeAttribute('disabled'); d = true; }
    if (el.hasAttribute('readonly')) { el.removeAttribute('readonly'); d = true; }
    if (d) rel.camposDesbloqueados++;
  });

  // 4. Remoção de elementos bloqueadores invisíveis (Overlays transparentes)
  document.querySelectorAll('div, section, span, aside').forEach((el) => {
    const s = window.getComputedStyle(el);
    const isFixedOrAbsolute = s.position === 'fixed' || s.position === 'absolute';
    const occupiesScreen = el.offsetWidth >= window.innerWidth * 0.8 && el.offsetHeight >= window.innerHeight * 0.8;
    if (isFixedOrAbsolute && occupiesScreen) {
      if (el.innerText.trim().length === 0) {
        el.remove();
        rel.overlaysRemovidos++;
      } else {
        el.style.pointerEvents = 'none';
        rel.overlaysRemovidos++;
      }
    }
  });

  // 5. Varredura de propriedades em cache interno (.value, innerText)
  document.querySelectorAll('input, select, textarea').forEach((el) => {
    const id = el.id || el.name || el.getAttribute('placeholder') || 'anônimo';
    const val = el.value || el.getAttribute('value') || el.innerText?.trim();
    if (val) {
      rel.valoresCacheColetados.push({
        elemento: el.tagName.toLowerCase(),
        identificador: id,
        tipo: el.type || 'text',
        valorReal: val
      });
    }
  });

  // 6. Varredura de atributos de acessibilidade (Aria-labels / Alt / Title)
  document.querySelectorAll('[aria-label], [aria-description], [title], [alt]').forEach((el) => {
    const txt = el.getAttribute('aria-label') || el.getAttribute('aria-description') || el.getAttribute('title') || el.getAttribute('alt');
    if (txt) {
      rel.metadadosAriaColetados.push({
        tag: el.tagName.toLowerCase(),
        identificador: el.id || el.className || 'sem-id',
        atributo: el.hasAttribute('aria-label') ? 'aria-label' : (el.hasAttribute('title') ? 'title' : 'outros'),
        textoOculto: txt
      });
    }
  });

  console.log(`✅ [1/6] Senhas desmascaradas: ${rel.senhasDesmascaradas}`);
  console.log(`✅ [2/6] Trava(s) visuais e filtros CSS sobrescritos: ${rel.travasCssRemovidas}`);
  console.log(`✅ [3/6] Elementos destravados (disabled/readonly): ${rel.camposDesbloqueados}`);
  console.log(`✅ [4/6] Overlays neutralizados: ${rel.overlaysRemovidos}`);
  console.log(`✅ [5/6] Valores em cache coletados: ${rel.valoresCacheColetados.length}`);
  if (rel.valoresCacheColetados.length > 0) console.table(rel.valoresCacheColetados);
  console.log(`✅ [6/6] Metadados de acessibilidade extraídos: ${rel.metadadosAriaColetados.length}`);
  if (rel.metadadosAriaColetados.length > 0) console.table(rel.metadadosAriaColetados.slice(0, 30));
  console.groupEnd();
  return rel;
})();

